// Director tools (after kaomei/stickman-video-director, MIT):
//   proposal.md — Phase A: the director's proposal (header, 5-stage storyboard, continuity, post-production overlays, checks)
//   <lang>/prompts.md + prompts.json — Phase B: standalone ~10-second prompts for AI video models (Gemini Omni Flash, Veo,
//   Kling…), each repeating the style anchor, cast cards, palette, timed beats with the exact narration, the frozen voice
//   block, the music lock, the ending state and negatives — so the same story can also be generated by a video model.
// Both are written by make.mjs next to the stills/video; `node make.mjs <slug> --director` writes only these files.
import { writeFileSync, mkdirSync } from 'node:fs';
import path from 'node:path';
import { localize, LOOKS, THEMES } from './story.mjs';

const STAGES = { hook: 'Golden hook', assumption: 'Disrupting assumptions', secret: 'Insider secret', truth: 'Truth revelation', elevation: 'Elevation & discussion',
  setup: 'Setup', escalation: 'Escalation', payoff: 'Ironic payoff' };
// infer the stage of scene i of n for an arc
export function stageOf(scene, i, n, arc = 'heartbeat') {
  if (scene.stage) return scene.stage;
  const k = n <= 1 ? 0 : i / (n - 1);
  if (arc === 'payoff') return k < .34 ? 'setup' : k < .99 ? 'escalation' : 'payoff';
  if (i === 0) return 'hook'; if (i === n - 1) return 'elevation';
  return k < .35 ? 'assumption' : k < .65 ? 'secret' : 'truth';
}
// ordinary colour names instead of codes (video models copy hex codes into the picture as text)
const NAMED = { black: '#111111', white: '#ffffff', grey: '#8a8a8a', 'vivid red': '#e8202a', 'deep red': '#8a2020', 'roman red': '#b8322a', orange: '#f28a2a', 'warm gold': '#d4a33a', yellow: '#f5c518',
  'grass green': '#5c8a4a', 'deep green': '#2f5a2a', teal: '#2f7f7a', cyan: '#19b8e6', 'electric blue': '#2f6fd6', indigo: '#2f4f7a', navy: '#1d2a4a', purple: '#7a5ea8', pink: '#f4b8c8',
  brown: '#7a4a24', tan: '#c49a62', ochre: '#c99a5a', cream: '#efe3c8' };
export function colorName(hex) {
  const m = String(hex || '').match(/^#?([0-9a-f]{6})$/i); if (!m) return hex;
  const v = [0, 2, 4].map(i => parseInt(m[1].slice(i, i + 2), 16)); let best = 'grey', bd = 1e9;
  for (const [n, h] of Object.entries(NAMED)) { const w = [1, 3, 5].map(i => parseInt(h.slice(i, i + 2), 16)), d = w.reduce((a, x, i) => a + (x - v[i]) ** 2, 0); if (d < bd) { bd = d; best = n; } }
  return best;
}
const deHex = str => String(str).replace(/#[0-9a-f]{6}/gi, h => colorName(h));
const fmt = s => `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, '0')}`;
const words = s => String(s || '').replace(/\[[^\]]*\]/g, ' ').split(/\s+/).filter(Boolean).length;
const loc = (v, l) => localize(v, l) ?? '';

// ─── style anchors for video-model prompts (Styles 1–5 adapted from the stickman director; others written for our looks) ──
const ANCHOR = {
  'stick-light': 'Use minimalist two-dimensional black line animation on a flat, uniform, digitally pure-white canvas with no shading, gradients, texture or 3D depth. Show the same consistent stick figure with a hollow circular head, occasional simple line expressions, no detailed facial features, no hair, no clothing, no filled body, stable proportions, connected line limbs, and uniform medium line weight. Exactly two arms and two legs are visible per figure; each limb appears only in its current pose. The figure stays black; accent colors affect only props and graphic effects.',
  'stick-dark': 'Use minimalist two-dimensional white line animation on a flat, uniform, pitch-black canvas. Show the same consistent stick figure with a hollow circular head, occasional simple line expressions, no detailed facial features, no hair, no clothing, no filled body, stable proportions, connected line limbs, and uniform medium line weight. Exactly two arms and two legs are visible per figure; each limb appears only in its current pose. The figure stays white; accent colors affect only props and graphic effects.',
  beanie: 'A minimalist 2D animated stick figure wearing a bright red beanie (smooth rounded knit, no pom-pom) and a yellow t-shirt, with simple black stick limbs and shorts, a white round face with minimal dot eyes. Simple black lines, vibrant colors, smooth 2D animation style.',
  prehistoric: 'Crude hand-drawn 2D animation with irregular black outlines and subtle paper texture: stick-figure characters with white filled round heads, expressive simple cartoon eyes, brows and mouths, thin black stick limbs and animal-hide clothing, in earthy ochre and brown prehistoric scenery with small warm fire accents.',
  cozy: 'One minimalist 2D cartoon protagonist with a white filled circular head, two small dark oval eyes, simple eyebrow strokes and a short curved mouth. The torso is a slim closed tapered shape with solid white fill inside its dark outline. Both arms and both legs are dark single-line strokes with constant medium weight; hands are small dark rounded shapes. Full-color 2D cartoon environments with gentle atmospheric light and depth.',
  history: 'Polished 2D cel-shaded cartoon animation with thick clean black outlines and soft shading. Stick-figure characters with smooth white filled round heads, simple black oval eyes, expressive brows and mouths, no nose, and thin black stick limbs, in the described costume. Exactly two arms and two legs, each shown only in its current pose. Clean, sunlit, painterly landscapes.',
  doodle: 'Hand-drawn black-and-white doodle animation on grey paper: TV-headed stick figures with simple faces on their screens, boiling pencil lines, floating pencil doodles and soft film grain.',
  cartoon: 'Warm flat-color 2D cartoon with thick dark-brown outlines, TV-headed characters with colored clothes and tube arms, a cozy night-garage palette, warm lamp light and soft film grain.',
};
const ENV = {
  studio: 'in a modern bright white studio space with subtle light-gray perspective grid lines on the floor plane. High-key studio lighting, clean white negative space, sleek glowing cyan and electric blue glass holographic UI elements.',
  dusk: 'on a vast open desert highway under a glowing dusk sky, cinematic volumetric lighting, soft depth of field.', summit: 'on a dramatic mountain ridge above rolling golden clouds at sunrise, cinematic light.',
  lamproom: 'in a dimly lit cozy bedroom with warm lamplight and a night window.', cave: 'inside a cave lit by a crackling campfire, simple wall paintings, rough rock arch.',
  camp: 'at a dusk camp with animal-hide tents and a campfire.', plains: 'on a sunny rocky plain with a river and a distant smoking volcano.',
  platform: 'on a bright metro platform while a blue train passes behind.', terrace: 'at a sunny street-side cafe terrace with striped awnings and parasols.', office2: 'in a colorful office with a city window and a small desk.',
  edo: 'Edo-period Japan: an earthen street of wooden houses with dark tiled roofs, red paper lanterns, a cherry tree and Mount Fuji in the distance.',
  egypt: 'an Ancient Egyptian temple with painted sandstone columns, pyramids and palms in the warm desert light.', rome: 'a Roman army camp: wooden palisade, white tents with red stripes, green hills and cypress trees, a dusty road.',
  garage: 'in a cozy night garage with a brick wall, a hanging lamp and a window on the city at night.',
};
const NEG = {
  base: 'no photorealism, no 3D humanoid CGI, no extra limbs, no malformed anatomy, no changed proportions or line weight, no unintended characters, no visible words, letters, numbers, captions, subtitles, logos or watermarks, no speech bubbles or dialogue boxes, no altered or repeated dialogue',
  beanie: 'strictly minimalist studio aesthetic, no circuit board textures, no sci-fi wall panels, no spaceship corridors, no cracked concrete, no grunge textures',
  history: 'no blood or gore, no paper texture, no fused or duplicate heads, no costume changes',
};
export function voiceBlock(lang, profile) {
  if (profile) return profile;
  return lang === 'ru'
    ? 'One off-screen adult male narrator throughout, speaking natural Russian. Warm clean baritone, medium-low pitch, gentle chest resonance, no raspiness or breathiness. Calm conversational delivery, restrained pitch variation, steady speaking pace, close dry studio sound. Keep the same timbre, register, accent, pace and recording quality throughout; emotional progression belongs to the visuals and music, not to the voice.'
    : 'One off-screen adult male narrator throughout. General American accent, warm clean baritone, medium-low pitch, gentle chest resonance, no raspiness or breathiness. Calm conversational delivery, restrained pitch variation, steady speaking pace, and close, dry studio sound. Keep the same vocal timbre, register, accent, pace, and recording quality throughout. Emotional progression belongs to the visuals and music; do not change the narrator\'s voice or switch to character dialogue.';
}
const MUSIC_TXT = { lofi: 'warm electric piano, dusty swung drums and soft vinyl crackle', ambient: 'quiet, thoughtful piano and subtle soft ambient synth', upbeat: 'bright plucked chords, light claps and a steady pop groove',
  chiptune: 'cheerful square-wave chiptune with noise drums', synthwave: 'dark saw-pad synthwave with a pulsing bass', epic: 'restrained drums, brass and strings', tribal: 'understated hand drums, wooden clicks and a low bone-flute drone',
  koto: 'plucked koto-like pentatonic strings over soft taiko' };

const anchorOf = (story, theme) => story.look === 'stick' ? ANCHOR[theme === 'stick-dark' || theme?.preset === 'stick-dark' ? 'stick-dark' : 'stick-light'] : ANCHOR[story.look || 'doodle'] || `${LOOKS[story.look]?.label || story.look} 2D motion-graphics animation.`;
function castCard(id, c, lang) {
  const bits = [loc(c.name, 'en') || id, loc(c.desc, 'en')].filter(Boolean);
  const parts = ['kind', 'head', 'body', 'hat', 'neck', 'back', 'glasses', 'hair', 'color', 'hold'].filter(k => c[k]).map(k => `${k}: ${deHex(c[k])}`).join(', ');
  return `${bits.join(' — ')}${parts ? ` (${parts})` : ''}`;
}

export function writeDirector({ story: raw, TLs, langs, outDir, format, voiceIds = {} }) {
  const first = langs.find(l => TLs[l]) || langs[0], TL = TLs[first]; if (!TL) return null;
  const story = localize(raw, 'en'), n = raw.scenes.length, arc = raw.arc || 'heartbeat', look = raw.look || 'doodle';
  const theme = typeof raw.theme === 'string' ? raw.theme : raw.theme?.preset || LOOKS[look]?.theme;
  const music = raw.music === false ? 'none' : raw.music || LOOKS[look]?.music || 'drone';
  const T = THEMES[theme] || {};
  const accents = [T.accent, T.accent2, T.accent3].filter(Boolean);
  const checks = [];
  // ── Phase A ──
  let md = `# Director's proposal — ${loc(raw.title, first) || 'untitled'}\n\n`;
  md += `| | |\n|---|---|\n| Title | ${langs.map(l => loc(raw.title, l)).filter(Boolean).join(' / ')} |\n| Hook | ${loc(raw.scenes[0].say, first)} |\n`;
  md += `| Format · length | ${format} · ${fmt(TL.duration)} (${Math.ceil(TL.duration / 10)} × ~10 s blocks) |\n| Look · palette | ${LOOKS[look]?.label || look} · ${theme}${accents.length ? ` (accents: ${accents.map(colorName).join(', ')})` : ''} |\n`;
  md += `| Narrative arc | ${arc === 'payoff' ? 'setup → escalation → ironic payoff' : '5-stage heartbeat: hook → disrupting assumptions → insider secret → truth → elevation & discussion'} |\n`;
  md += `| Narrator | ${langs.map(l => `${l.toUpperCase()}: Fish voice ${voiceIds[l] || 'default'}`).join(' · ')} — one frozen voice for the whole video |\n| Music | ${music}${MUSIC_TXT[music] ? ` — ${MUSIC_TXT[music]}` : ''}; drums drop out in dark scenes, hits on zoom / iris / whip seams |\n\n`;
  md += `## Storyboard\n\n| # | Time | Stage | Picture | Motion · camera · seam | ${langs.map(l => `VO ${l.toUpperCase()}`).join(' | ')} |\n|---|---|---|---|---|${langs.map(() => '---').join('|')}|\n`;
  const events = [];
  raw.scenes.forEach((sc, i) => {
    const s = TL.scenes[i]; if (!s) return;
    const dur = s.to - s.from, st = stageOf(sc, i, n, arc);
    const cast = (sc.cast || []).map(c => `${c.id}${c.pose ? ' ' + c.pose : ''}${c.face ? '/' + c.face : ''}`).join(', ');
    const props = (sc.props || []).map(p => p.type).join(', ');
    const motion = [s.transition?.type && i ? `seam: ${s.transition.type}` : '', sc.cam ? `cam: ${typeof sc.cam === 'string' ? sc.cam : 'custom'}` : '', sc.ae ? `AE 3D: ${typeof sc.ae === 'string' ? sc.ae : sc.ae.recipe}` : '', cast, props].filter(Boolean).join(' · ');
    md += `| ${i + 1} | ${fmt(s.from)}–${fmt(s.to)} | ${STAGES[st] || st} | ${loc(sc.note, first) || ''}${sc.set ? ` *(set: ${typeof sc.set === 'string' ? sc.set : sc.set.type})*` : ''} | ${motion} | ${langs.map(l => loc(sc.say, l) || '—').join(' | ')} |\n`;
    // checks: narration density (EN ≈ 20–25 words / 10 s) and visual events every 2–3 s
    const wc = words(loc(sc.say, first)), per10 = dur > 0 ? wc / dur * 10 : 0;
    if (wc && (per10 > 30 || per10 < 12)) checks.push(`Scene ${i + 1}: ${per10.toFixed(0)} words per 10 s (aim ~20–25 in English, a little less in Russian).`);
    const ev = s.items.reduce((a, it) => a + 1 + (it.then || []).length, 0) + (i ? 1 : 0);
    events.push(ev);
    if (dur > 4 && dur / Math.max(1, ev) > 3.5) checks.push(`Scene ${i + 1}: one visual event per ${(dur / Math.max(1, ev)).toFixed(1)} s — add a change, cue or camera move every 2–3 s.`);
  });
  if (arc === 'heartbeat' && !/\?\s*$/.test(loc(raw.scenes[n - 1].say, first).trim())) checks.push('Heartbeat arc: the last line is not a question — end on a punchline plus an open question for the comments.');
  md += `\n## Continuity\n\n` + raw.scenes.slice(1).map((sc, i) => { const a = raw.scenes[i], shared = (sc.cast || []).filter(c => (a.cast || []).some(b => b.id === c.id)).map(c => c.id);
    return `- ${i + 1} → ${i + 2}: ${TL.scenes[i + 1]?.transition?.type || 'cut'}${sc.keep ? ', same picture continues' : ''}${shared.length ? `; carries ${shared.join(', ')}` : ''}${(sc.set && a.set && JSON.stringify(sc.set) !== JSON.stringify(a.set)) ? '; new location' : ''}`; }).join('\n') + '\n';
  const overlays = raw.scenes.flatMap((sc, i) => (sc.props || []).filter(p => ['text', 'words', 'headline', 'badge', 'stamp'].includes(p.type)).map(p => `- scene ${i + 1}: ${loc(p.text ?? p.title ?? p.name, first)}`)).filter(l => !/: $/.test(l));
  md += `\n## On-screen text (post-production overlays)\n\n${overlays.length ? overlays.join('\n') : '- none'}\n`;
  md += `\n## Checks\n\n${checks.length ? checks.map(c => `- ⚠ ${c}`).join('\n') : '- ✓ narration density, visual rhythm and ending look fine'}\n`;
  mkdirSync(outDir, { recursive: true });
  writeFileSync(path.join(outDir, 'proposal.md'), md);

  // ── Phase B: one prompt per ~10 s ──
  for (const lang of langs) {
    const tl = TLs[lang]; if (!tl) continue;
    const S = localize(raw, lang), N = Math.max(1, Math.round(tl.duration / 10)), clips = [];
    const words = tl.subs.flatMap(p => p.words);
    // cut points: near each 10 s mark prefer a sentence end, then a scene cut, then any word gap (±3 s)
    const cuts = [0];
    for (let k = 1; k < N; k++) {
      const target = k * tl.duration / N, lo = Math.max(cuts[k - 1] + 4, target - 3), hi = target + 3;
      const sent = words.filter(([, t], i) => i && t >= lo && t <= hi && /[.!?…]$/.test(words[i - 1][0])).map(w => w[1] - .05);
      const scene = tl.scenes.map(sc => sc.from).filter(t => t >= lo && t <= hi);
      const gap = words.filter(([, t]) => t >= lo && t <= hi).map(w => w[1] - .05);
      const pool = sent.length ? sent : scene.length ? scene : gap.length ? gap : [target];
      cuts.push(pool.reduce((a, b) => Math.abs(b - target) < Math.abs(a - target) ? b : a));
    }
    cuts.push(tl.duration);
    const anchor = anchorOf(raw, theme), voice = voiceBlock(lang, localize(raw.voiceProfile, lang));
    const castAll = raw.characters || {};
    for (let k = 0; k < N; k++) {
      const a = cuts[k], b = cuts[k + 1], step = b - a;
      const scIdx = tl.scenes.map((s, i) => ({ s, i })).filter(({ s }) => s.to > a + .05 && s.from < b - .05).map(o => o.i);
      const sets = [...new Set(scIdx.map(i => { const v = raw.scenes[i].set ?? null; return typeof v === 'string' ? v : v?.type; }).filter(Boolean))];
      const env = sets.map(st => ENV[st] || st).join(' Then ') || (look === 'stick' ? '' : 'in a setting that matches the narration.');
      const ids = [...new Set(scIdx.flatMap(i => (raw.scenes[i].cast || []).map(c => c.id)))];
      const cards = ids.map(id => castCard(id, castAll[id] || {}, lang));
      const beats = [[0, 3], [3, 7], [7, 10]].map(([x, y]) => {
        const ta = a + x * step / 10, tb = a + y * step / 10;
        const vo = words.filter(([, t]) => t >= ta && t < tb).map(w => w[0]).join(' ');
        const sc = tl.scenes.findIndex(s => (ta + tb) / 2 >= s.from && (ta + tb) / 2 < s.to), r = raw.scenes[sc] || raw.scenes[raw.scenes.length - 1];
        const act = (r.cast || []).map(c => `${loc(castAll[c.id]?.name, 'en') || c.id} ${c.pose || 'idle'}${c.face ? ' (' + c.face + ')' : ''}`).join(', ');
        const pr = (r.props || []).map(p => p.type).join(', ');
        return `- [${x}–${y}s]${vo ? ` (VO: "${vo}")` : ''}: ${loc(r.note, 'en') || ''}${act ? `. Action: ${act}` : ''}${pr ? `. Visual devices: ${pr}` : ''}.`;
      });
      const vo = words.filter(([, t]) => t >= a && t < b).map(w => w[0]).join(' ');
      const next = tl.scenes.find(s => s.from >= b - .05), nextNote = next ? loc(raw.scenes[tl.scenes.indexOf(next)].note, 'en') : 'final frame holds';
      const neg = [NEG.base, look === 'beanie' && sets.includes('studio') ? NEG.beanie : '', look === 'history' ? NEG.history : ''].filter(Boolean).join(', ');
      const mus = MUSIC_TXT[music] || 'a gentle underscore';
      const text = [
        `Output: approximately ${Math.round(step)} seconds, ${format}, 720p target, 24 FPS, synchronized audio.`,
        `Style: ${anchor}`, env ? `Environment: ${env}` : '',
        cards.length ? `Characters: ${cards.join('; ')}. Repeat these exact designs; no other characters.` : '',
        accents.length && look === 'stick' ? `Palette: monochrome figure and canvas; up to three saturated accents on props only (vivid red, electric blue, warm gold).` : '',
        `Composition: ${format === '9:16' ? 'vertical frame — foreground/background depth, vertical reveals, keep the lower fifth clear' : 'left-center-right staging, lateral tracking, deliberate negative space'}.`,
        k ? `First frame: continues from the previous clip's ending.` : '',
        `Timed visual beats (rapid scene changes and frequent visual events while preserving an identical character design and constant line weight):\n${beats.join('\n')}`,
        vo ? `Audio voiceover only, strictly no speech bubbles, no dialogue boxes. Exact narration, do not add, omit, repeat or caption words: "${vo}"` : 'No narration in this clip.',
        `Voice: ${voice}`,
        k ? `Audio: voiceover seamlessly continues the identical ${mus} from clip 1, same tempo and instrumentation; synchronized crisp SFX on physical actions; voice-first mix.` : `Audio: voiceover clearly audible over ${mus}; synchronized crisp SFX on physical actions; voice-first mix.`,
        `Final frame: sets up the next clip — ${nextNote}.`,
        `Negative constraints: ${neg}.`,
      ].filter(Boolean).join('\n');
      clips.push({ clip: k + 1, from: +a.toFixed(2), to: +b.toFixed(2), scenes: scIdx.map(i => i + 1), prompt: deHex(text) });
    }
    const pm = `# AI-video prompt package — ${loc(raw.title, lang) || ''} (${lang.toUpperCase()})\n\nFor Gemini Omni Flash, Veo, Kling or similar: ${clips.length} standalone ~10-second prompts. Each repeats the style, cast, voice and music locks, so clips can be generated independently and stitched in order.\n\n` +
      `## Global continuity\n\n- Format ${format}, ${fmt(tl.duration)}, look ${LOOKS[look]?.label || look}\n- Style anchor: ${anchor}\n- Voice (verbatim in every clip): ${voice}\n- Music: ${MUSIC_TXT[music] || music}\n\n` +
      clips.map(c => `## Clip ${c.clip} · ${fmt(c.from)}–${fmt(c.to)} · scenes ${c.scenes.join(', ')}\n\n\`\`\`text\n${c.prompt}\n\`\`\``).join('\n\n') +
      `\n\n## Stitching guide\n\n${clips.map(c => `${c.clip}. ${fmt(c.from)}–${fmt(c.to)}`).join(' → ')}. Trim to usable frames at each join and add a short audio crossfade; the voice block and music line stay identical in every prompt.\n`;
    const ld = path.join(outDir, lang); mkdirSync(ld, { recursive: true });
    writeFileSync(path.join(ld, 'prompts.md'), pm);
    writeFileSync(path.join(ld, 'prompts.json'), JSON.stringify({ format, duration: tl.duration, look, clips }, null, 2));
  }
  return { proposal: path.join(outDir, 'proposal.md'), checks };
}
